/* The activity panel's steps and what was said between them read at the
   size of the commands they run. */
.mono-activity-steps .text-sm {
  font-size: 13px;
  line-height: 20px;
}

.mono-activity-prose .mono-run-report.agent-markdown {
  font-size: 13px;
}

/* Reader frames supply their own inset, so a leading heading's mt-6 would
   only double the top padding. */
[data-artifact-reader] .agent-markdown > :first-child,
[data-artifact-reader] .agent-markdown > .agent-markdown-block:first-child > * {
  margin-top: 0;
}

.agent-chat-bubble-md.agent-markdown > :first-child,
.agent-chat-bubble-md.agent-markdown > .agent-markdown-block:first-child > * {
  margin-top: 0;
}

.agent-chat-bubble-md.agent-markdown > :last-child,
.agent-chat-bubble-md.agent-markdown > .agent-markdown-block:last-child > * {
  margin-bottom: 0;
}

/* Inline code must fit inside the dots' 24px line box. A 24px inline-flex
   badge on the text baseline makes even a one-line reply a pixel taller. */
.agent-chat-bubble-md.agent-markdown :not(pre) > code {
  min-height: 0;
  line-height: 1.4;
}

/* Shaded pixel mascots. Motion moves half a sprite cell at a time and stays
   unhurried; blinks swap in closed eyes instead of squashing open ones. */
.pixel-bob {
  animation: pixel-bob 3.6s step-end infinite;
}

.pixel-hop {
  animation: pixel-bob 1.2s step-end infinite;
}

.pixel-frame-a {
  animation: pixel-frame-a 600ms step-end infinite;
}

.pixel-frame-b {
  opacity: 0;
  animation: pixel-frame-b 600ms step-end infinite;
}

.pixel-eyes-open {
  animation: pixel-eyes-open 5.2s step-end infinite;
}

.pixel-eyes-closed {
  opacity: 0;
  animation: pixel-eyes-closed 5.2s step-end infinite;
}

.pixel-bulb {
  animation: pixel-flicker 2.4s step-end infinite;
}

@keyframes pixel-bob {
  0% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-0.75px);
  }
}

