178	  onMenu?: (anchor: PopoverAnchor) => void;
179	}) {
180	  // A long press opens the menu too (a trackpad without a right-click habit); the click that ends it doesn't open the project.
181	  const press = useRef<{ timer: ReturnType<typeof setTimeout>; fired: boolean } | undefined>(undefined);
182	  const endPress = () => {
183	    if (press.current) clearTimeout(press.current.timer);
184	  };
185	  return (
186	    <div className="group/strip relative">
187	    <button
188	      type="button"
189	      title={title}
190	      aria-label={title}
191	      aria-current={selected || undefined}
192	      onClick={() => {
193	        if (press.current?.fired) {
194	          press.current = undefined;
195	          return;
196	        }
197	        onClick();
198	      }}
199	      onPointerDown={onMenu ? (e) => {
200	        if (e.button !== 0) return;
201	        const at = { x: e.clientX, y: e.clientY };
202	        endPress();
203	        press.current = { fired: false, timer: setTimeout(() => { if (press.current) press.current.fired = true; onMenu(at); }, LONG_PRESS_MS) };
204	      } : undefined}
205	      onPointerUp={onMenu ? endPress : undefined}
206	      onPointerLeave={onMenu ? endPress : undefined}
207	      onContextMenu={onMenu ? (e) => { e.preventDefault(); endPress(); onMenu({ x: e.clientX, y: e.clientY }); } : undefined}
