98	/** The word a job's state reads as; a state Ash OS named that this app doesn't know reads as its own word. */
99	export function jobStateWord(w: Worker): string {
100	  const state = jobState(w);
101	  return state === "unknown" ? (w.stateWord ?? "Unknown") : STATE_WORD[state];
102	}
103	
104	/** Opening a Done job marks it seen; leaving it archives it. */
105	export function markSeen(id: string): void {
106	  const w = WORKERS.find((x) => x.id === id);
107	  if (w?.finishedAt && !w.seen) { w.seen = true; changed(); }
108	}
109	export function archiveIfSeen(id: string): void {
110	  const w = WORKERS.find((x) => x.id === id);
111	  if (w?.finishedAt && w.seen && !w.archived) { w.archived = true; changed(); }
112	}
