114	export function activeWorkers(projectId: string): Worker[] {
115	  return WORKERS.filter((w) => w.projectId === projectId && !w.finishedAt);
116	}
117	export function finishedToday(projectId: string): Worker[] {
118	  return WORKERS.filter((w) => w.projectId === projectId && w.finishedAt && !w.archived);
119	}
120	export function getWorker(id: string): Worker | undefined {
121	  return WORKERS.find((w) => w.id === id);
122	}
123	export function durationLabel(min: number): string {
124	  if (min < 60) return `${min} min`;
125	  const m = min % 60;
126	  return m ? `${Math.floor(min / 60)} h ${m} min` : `${Math.floor(min / 60)} h`;
127	}
