131	 * on something ... I would have to just go to the chat and find out why it's stuck. Or the lead would just tell me").
132	 * The old red Stuck stays behind the dev flag `monocode:hub-gaveup-style=stuck`, for comparison only.
133	 */
134	export function gaveUpAsNeedsYou(): boolean {
135	  try { return localStorage.getItem("monocode:hub-gaveup-style") !== "stuck"; } catch { return true; }
