542	/** The Lead running a job, from Ash OS's job list: its Mono id and name. */
543	function jobLead(jobId: string): { id: string | null; name: string } | undefined {
544	  const data = hubData();
545	  for (const p of data.listProjects())
546	    for (const g of data.listJobs?.(p.id) ?? []) {
547	      const j = g.jobs.find((x) => x.id === jobId);
548	      if (j) return { id: j.lead ?? g.leadId, name: g.leadName };
549	    }
550	  return undefined;
551	}
