553	function NeedRow({ need, onSheet, counted = false }: { need: Need; onSheet?: (sheet: SheetFor) => void; counted?: boolean }) {
554	  const done = need.state === "done";
555	  const [busy, setBusy] = useState(false);
556	  const [problem, setProblem] = useState<string | null>(null);
557	  const data = hubData();
558	  // One action per row, as Ash OS names it: Looks right accepts; See options opens the job's or the question's
559	  // sheet; an older Looks-right row (action "open") is marked seen; Open and Start show the row in full.
560	  const accept = need.actionType === "accept" && !!data.acceptNeed;
561	  const seen = need.canMarkSeen && need.actionType !== "accept" && !!data.markNeedSeen;
562	  const isQuestion = !!need.actionTarget?.startsWith("question:");
563	  const answering = data.answerState?.(need.id);
564	  const mark = needMark(need, counted);
565	  const askRed = askNeedsAsh(need, counted);
566	  // A red ask keeps its one action (See options answers it right here), so it carries no Lead link: one action per row.
567	  const lead = need.jobId ? jobLead(need.jobId) : undefined;
568	  const run = async (call: () => Promise<void>) => {
569	    setBusy(true);
570	    setProblem(null);
571	    try {
572	      await call();
573	    } catch (e) {
574	      setProblem(e instanceof Error ? e.message : "That didn't go through.");
575	      setBusy(false);
576	    }
577	  };
578	  const onAction = async () => {
579	    if (need.jobId && data.jobOptions) return onSheet?.({ kind: "job", jobId: need.jobId });
580	    if (accept) return run(() => data.acceptNeed!(need.id));
581	    if (seen) return run(() => data.markNeedSeen!(need.id));
582	    if (isQuestion && data.question) return onSheet?.({ kind: "question", needId: need.id });
583	    if (need.actionType === "open" || need.actionType === "start") return onSheet?.({ kind: "detail", need });
584	  };
585	  return (
586	    <div className="flex items-center gap-3 rounded-md px-2 py-2 hover:bg-content/5" data-hub-need={need.id} data-hub-need-done={done || undefined} data-hub-ask-reason={askRed ? askReason(need) : undefined} {...redRowProps(!done && mark?.circle === "red")}>
587	      <div className="min-w-0 flex-1">
588	        <div className={`truncate text-[13px] ${done ? "text-content/60" : "text-content"}`}>{need.title}</div>
589	        {/* The reason wraps (never cut mid-word). */}
590	        <div className="whitespace-normal break-words text-[13px] leading-5 text-content/60" data-hub-need-why>{need.why}</div>
591	        {/* A red Needs you opens the Lead's chat from its row (r27b); the reason is the line above. */}
592	        {mark?.circle === "red" && lead?.id ? <NeedsYouLinkLine name={lead.name} onOpen={() => openLead(lead.id) || openMonoChat(lead.id!)} /> : null}
593	        {problem ? <div className="text-[13px] text-content/60" data-hub-need-problem>{problem}</div> : null}
594	        {answering && !answering.sending && (answering.receipt || answering.problem) ? (
595	          <div className="text-[13px] leading-5 text-content/85" data-hub-answer-receipt>{answering.receipt ?? answering.problem}</div>
596	        ) : null}
597	      </div>
598	      {done ? (
599	        // It ticked itself off (answered or cleared somewhere else). It stays here until Ash leaves the page.
600	        <span className="grid size-6 shrink-0 place-items-center text-content/60" role="img" aria-label="Done">
601	          <Check className="size-3.5" strokeWidth={1.75} />
602	        </span>
603	      ) : answering?.sending ? (
604	        // His answer is on its way (the model can take a minute); nothing else waits for it.
605	        <span className="shrink-0 text-xs text-content/60" data-hub-sending>Sending…</span>
606	      ) : (
607	        <>
608	          {mark ? <CircleWord circle={mark.circle} word={mark.word} /> : null}
609	          <button
610	            type="button"
611	            disabled={busy}
612	            onClick={() => void onAction()}
613	            className="shrink-0 rounded-md bg-content/8 px-2.5 py-1 text-xs text-content/85 hover:bg-content/12 disabled:opacity-60"
614	          >
615	            {seen ? "Seen" : need.actionLabel}
616	          </button>
617	        </>
618	      )}
619	    </div>"}]},"parent_tool_use_id":null,"session_id":"607ed927-3971-46aa-902d-f607f68c0c9b","uuid":"09b7fb8a-1997-4b04-bee3-8979d0eb504a","timestamp":"2026-10-31T07:52:04.280Z","tool_use_result":{"type":"text","file":{"filePath":"/private/var/folders/b4/8qh0t36j0_g9srqzx1g5t3z40000gn/T/monocode-realtest-LTcosa/home/Library/Application Support/com.ash.monocode-hub.dev.cos-r62-realtest/hub-changes/hc-mvw3m10bqcva/src/features/hub/ui/HubSurface.tsx","content":"  return (
