import { keybindingPressed } from "../../settings/model/settings";

type Props = {
  blocks: Block[];
  visible: boolean;
  focused: boolean;
  onNavigate: (
    blockId: string | null,
    query?: string,
  ) => boolean | Promise<boolean>;
  onSearch?: (query: string) => Promise<string[]>;
  side?: "left" | "right";
};

export function TranscriptFind({
  blocks,
  visible,
  focused,
  onNavigate,
  onSearch,
  side = "right",
}: Props) {
  const input = useRef<HTMLInputElement>(null);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [storedMatches, setStoredMatches] = useState<string[]>([]);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState(false);
  const localMatches = useMemo(
    () => findTranscriptBlocks(blocks, query),
    [blocks, query],
  );
  const matches = useMemo(() => {
    if (!onSearch) return localMatches;
    // Search the archive once per query; streamed blocks keep matching locally.
    const liveIds = new Set(blocks.map((block) => block.id));
    const localIds = new Set(localMatches);
    return [
      ...new Set([
        ...storedMatches.filter((id) => !liveIds.has(id) || localIds.has(id)),
        ...localMatches,
      ]),
    ];
  }, [onSearch, storedMatches, blocks, localMatches]);
  useEffect(() => {
    if (!onSearch || !open || !query.trim()) {
      setStoredMatches([]);
      setSearching(false);
      return;
    }
    let cancelled = false;
    setSearching(true);
    setStoredMatches([]);
    setSearchError(false);
    const timer = setTimeout(() => {
      void onSearch(query)
        .then((ids) => {
          if (!cancelled) setStoredMatches(ids);
        })
        .catch(() => {
          if (!cancelled) {
            setStoredMatches([]);
            setSearchError(true);
          }
        })
        .finally(() => {
          if (!cancelled) setSearching(false);
        });
    }, 150);","numLines":80,"startLine":1,"totalLines":251}},"tool_result_meta":[{"id":"call-f40a4edf-a795-4c49-9996-871ad9245691-73","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}]}

