{"type":"user","message":{"role":"user","content":[{"tool_use_id":"call-3fc91a4e-4611-4167-a204-f23257aded50-12","type":"tool_result","content":"1	// What waits on Ash for each project, counted once and the same wherever it shows (SPEC: "every count matches the items
2	// you can see"): the project card on Today and the strip badge both count the open rows Today shows for the project
3	// (waiting.ts: stuck rows, Needs, proposals), its chats waiting on Ash (Waiting on you), its stuck workers and its Monos
4	// that can't answer (the Stuck section). The baseline's Tally card said "0 needs" while Waiting on you had its question.
5	import { projectKey } from "../../../shared/lib/paths";
6	import { delegationRows, useDelegationsVersion } from "../../monos/model/delegationStore";
7	import { findMono, monoForSession } from "../../monos/model/mono";
8	import { monoFailures, useMonoFailuresVersion, type MonoFailure } from "../../monos/model/monoFailures";
9	import { stuckOwner, stuckWorkers, useStuckDismissalsVersion, type StuckWorker } from "../../monos/model/workerStuck";
10	import { hubData } from "./hubData";
11	import { leadFor } from "./hubLeads";
12	import { waitingCount } from "./waiting";
13	import { useWaitingChatsVersion } from "./waitingChats";
14	
15	/** The hub project a Mono works for: the project it leads, else its only project. */
16	export function monoProject(monoId: string | null | undefined): { id: string; name: string; shortName: string } | null {
17	  if (!monoId) return null;
18	  const projects = hubData().listProjects();
19	  const byLead = leadFor(monoId)?.projectId;
20	  const mono = findMono(monoId);
21	  const hit =
22	    projects.find((p) => p.id === byLead) ??
23	    (mono?.projects.length === 1 ? projects.find((p) => p.folder && projectKey(p.folder) === projectKey(mono.projects[0])) : undefined);
24	  return hit ? { id: hit.id, name: hit.name, shortName: hit.shortName } : null;
25	}
26	
27	/** The hub project a stuck worker's work belongs to: its Lead's project, else the row's project or folder. */
28	export function stuckProject(stuck: Pick<StuckWorker, "row">): { id: string; name: string; shortName: string } | null {
29	  const projects = hubData().listProjects();
30	  const monoId = stuck.row.ownerMono ?? monoForSession(stuck.row.ownerSession)?.id;
31	  const byLead = monoId ? leadFor(monoId)?.projectId : undefined;
32	  const where = stuck.row.project ?? "";
33	  const hit =
34	    projects.find((p) => p.id === byLead) ??
35	    projects.find((p) => p.id === where) ??
36	    (where ? projects.find((p) => p.folder && projectKey(p.folder) === projectKey(where)) : undefined) ??
37	    (monoId && findMono(monoId)?.projects.length === 1
38	      ? projects.find((p) => p.folder && projectKey(p.folder) === projectKey(findMono(monoId)!.projects[0]))
39	      : undefined);
40	  return hit ? { id: hit.id, name: hit.name, shortName: hit.shortName } : null;
41	}
42	
43	/** The Monos whose last turn failed, Today's (every one) or one project's. */
44	export function failedMonosFor(projectId: string | undefined): MonoFailure[] {
45	  const all = monoFailures();
46	  return projectId ? all.filter((failure) => monoProject(failure.monoId)?.id === projectId) : all;
47	}
48	
49	/** The stuck workers Today's Stuck section lists for one project. */
50	export function stuckWorkersFor(projectId: string, now = Date.now()): StuckWorker[] {
51	  return stuckWorkers(delegationRows(), now).filter((stuck) => stuckProject(stuck)?.id === projectId);
52	}
53	
54	/**
55	 * Whether a stuck worker counts as waiting on Ash: only a red "needs you" one. r63 (PM's blind D5 on 0.16.3): two failed
56	 * workers sat grey "With Hivra lead" and the Lead closed the job out, yet the badge went from 7 to 9 waiting on you. A
57	 * worker that is its Lead's or a retry's is never Ash's to count.
58	 */
59	export function stuckNeedsAsh(stuck: Pick<StuckWorker, "kind" | "row">): boolean {
60	  return stuckOwner(stuck) === "needs-you";
61	}
62	
63	/** Everything waiting on Ash for this project (the card and the strip badge read this one number): grey rows aren't. */
64	export function attentionCount(projectId: string, now = Date.now()): number {
65	  // r100 (d, B5 fc68): a failed Mono (its folder missing after a reopen) is not an ask; it stays in its own Stuck
66	  // row, but the badge counts only what waits on Ash's answer, so Hivra and Nibbii no longer show a stray "1".
67	  return waitingCount(projectId) + stuckWorkersFor(projectId, now).filter(stuckNeedsAsh).length;
68	}
69	
70	/** Re-render when anything the count reads changes (the Needs and proposals have their own versions at the caller). */
71	export function useAttentionVersion(): void {
72	  useWaitingChatsVersion();
73	  useMonoFailuresVersion();
74	  useDelegationsVersion();
75	  useStuckDismissalsVersion();
76	}
