const subs = new Set<() => void>();
export function useWorkVersion(): number {
  return useSyncExternalStore((f) => { subs.add(f); return () => subs.delete(f); }, () => version);
}
const changed = () => { version++; subs.forEach((f) => f()); };

export function jobState(w: Worker): JobState {
  if (w.finishedAt) return w.seen ? "done" : "done_unseen";
  if (w.stuck) return w.stuck === "lead_gave_up" ? (gaveUpAsNeedsYou() ? "needs_you" : "gave_up") : "stuck";
  return w.state ?? "working";
}
const STATE_WORD: Record<Exclude<JobState, "unknown">, string> = {
  working: "Working",
  checking: "Checking",
  waiting: "Waiting",
  // The red rule (r30b): never "Stuck". A job still with its Lead reads a calm grey Retrying (statusChip.ts reads it so);
  // one its Lead gave up on is Ash's (D5), even under the old dev flag.
  stuck: "Retrying",
  gave_up: "Needs you",
  needs_you: "Needs you",
  done_unseen: "Done",
  done: "Done",
  // Ash OS's "parked" is a job Ash paused (r28b).
  parked: "Paused by you",
  waiting_ci: "Waiting on CI",
};

/** The word a job's state reads as; a state Ash OS named that this app doesn't know reads as its own word. */
export function jobStateWord(w: Worker): string {
  const state = jobState(w);
  return state === "unknown" ? (w.stateWord ?? "Unknown") : STATE_WORD[state];
}

/** Opening a Done job marks it seen; leaving it archives it. */
export function markSeen(id: string): void {
  const w = WORKERS.find((x) => x.id === id);
  if (w?.finishedAt && !w.seen) { w.seen = true; changed(); }
}
export function archiveIfSeen(id: string): void {
  const w = WORKERS.find((x) => x.id === id);
  if (w?.finishedAt && w.seen && !w.archived) { w.archived = true; changed(); }
}

export function activeWorkers(projectId: string): Worker[] {
  return WORKERS.filter((w) => w.projectId === projectId && !w.finishedAt);
}
export function finishedToday(projectId: string): Worker[] {
  return WORKERS.filter((w) => w.projectId === projectId && w.finishedAt && !w.archived);
}
export function getWorker(id: string): Worker | undefined {
  return WORKERS.find((w) => w.id === id);
}
export function durationLabel(min: number): string {
  if (min < 60) return `${min} min`;
  const m = min % 60;
  return m ? `${Math.floor(min / 60)} h ${m} min` : `${Math.floor(min / 60)} h`;
}

/**
 * D5 (Ash, 21 Oct 20:40): a job the Lead gave up on goes to Needs you, not a separate red Stuck ("it would be needs me
 * on something ... I would have to just go to the chat and find out why it's stuck. Or the lead would just tell me").
 * The old red Stuck stays behind the dev flag `monocode:hub-gaveup-style=stuck`, for comparison only.
 */
export function gaveUpAsNeedsYou(): boolean {
  try { return localStorage.getItem("monocode:hub-gaveup-style") !== "stuck"; } catch { return true; }
}

/** Quiet last-active label: Now, 2m, 1h, 3d. Finished jobs: their finish time. */
export function lastActiveLabel(w: Worker): string {
  if (w.finishedAt) return w.finishedAt;
  const m = w.activeAgo ?? 0;
  if (m < 1) return "Now";
  if (m < 60) return `${m}m`;
  if (m < 1440) return `${Math.floor(m / 60)}h`;
  return `${Math.floor(m / 1440)}d`;
}
