 * Finished between last night and this morning. Clock labels like "4:10am", or an
 * ISO time from 10pm yesterday through 5am today. Afternoon times ("4:20pm") are not.
 */
export function finishedOvernight(finishedAt: string, now = new Date()): boolean {
  const clock = finishedAt.trim().match(/^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$/i);
  if (clock) {
    const hour = Number(clock[1]);
    return clock[3].toLowerCase() === "am" && (hour === 12 || hour < 7);
  }
  const parsed = Date.parse(finishedAt);
  if (!Number.isFinite(parsed)) return false;
  const morning = new Date(now);
  morning.setHours(5, 0, 0, 0);
  const night = new Date(morning);
  night.setDate(night.getDate() - 1);
  night.setHours(22, 0, 0, 0);
  return parsed >= night.getTime() && parsed < morning.getTime();
}

