type Offer = { title: string; onUndo: () => void };

let node: HTMLDivElement | null = null;
let timer = 0;

function dismiss(): void {
  window.clearTimeout(timer);
  node?.remove();
  node = null;
}

export function offerArchiveUndo(title: string, onUndo: () => void): void {
  dismiss();
  const offer: Offer = { title, onUndo };
  const el = document.createElement("div");
  el.setAttribute("role", "status");
  el.setAttribute("data-archive-undo", "");
  el.className =
    "fixed bottom-4 left-1/2 z-[80] flex -translate-x-1/2 items-center gap-3 rounded-lg border border-stroke bg-background-base px-3 py-2 text-[13px] text-content shadow-lg";
  const label = document.createElement("span");
  label.textContent = offer.title ? `Archived “${offer.title}”` : "Archived";
  const button = document.createElement("button");
  button.type = "button";
  button.textContent = "Undo";
  button.className = "font-medium text-accent";
  button.addEventListener("click", () => {
    const run = offer.onUndo;
    dismiss();
    run();
  });
  el.append(label, button);
  document.body.append(el);
  node = el;
  timer = window.setTimeout(dismiss, 6000);
}
